cat >/tmp/rename-patch.ts <<'TS'
import { readFileSync, writeFileSync, existsSync, mkdirSync, renameSync, cpSync } from "node:fs";
import { execSync } from "node:child_process";

const ROOT="/home/toxic/sovereign";
const RANCH="/home/toxic/sovereign/projects/range/ranch";

// 1. filesystem: barn/shep -> barn/wrangler (already mv'd, verify)
console.log(execSync(`ls -d ${RANCH}/barn/wrangler 2>&1 | tr -d '\\0' | strings | awk 'length<2000'`).toString().trim()||"MISSING wrangler");

// 2. bin/wrangler: copy ELF binary same as wrangler-serve.sh
if (!existsSync(`${RANCH}/bin/wrangler`)) {
  cpSync(`${RANCH}/bin/shep`, `${RANCH}/bin/wrangler`);
  console.log("cp shep -> wrangler ELF");
}
if (existsSync(`${RANCH}/bin/shep-v0.51.0`) && !existsSync(`${RANCH}/bin/wrangler-v0.51.0`)) {
  cpSync(`${RANCH}/bin/shep-v0.51.0`, `${RANCH}/bin/wrangler-v0.51.0`);
  console.log("cp shep-v0.51.0 -> wrangler-v0.51.0");
}

// 3. helpers
const patch = (file: string, fn: (s:string)=>string|null)=>{
  if(!existsSync(file)){ console.log(`SKIP ${file} no file`); return; }
  let s=readFileSync(file,"utf8"); let n=fn(s);
  if(n===null){ console.log(`SKIP ${file} no match`); return; }
  writeFileSync(file,n); console.log(`PATCH ${file}`);
};

// Find & patch files referencing barn/shep or shep daemon/binary (monadic: try->catch->forward)
const targets: [string, (s:string)=>string|null][] = [
  [`${ROOT}/pitchfork.toml`, s=>{
    if(!s.includes("daemons.shep")) return null;
    let o=s;
    // daemon name + dir + run
    o=o.replaceAll("[daemons.shep]","[,daemons.wrangler,]");
    // temp marker to avoid double-replace then fix
    o=o.replaceAll("[,daemons.wrangler,]","[daemons.wrangler]");
    o=o.replaceAll('dir = "/home/toxic/sovereign/projects/range/ranch/barn/shep"','dir = "/home/toxic/sovereign/projects/range/ranch/barn/wrangler"');
    o=o.replaceAll("bin/shep-serve.sh","bin/wrangler-serve.sh");
    o=o.replaceAll('depends = ["shep"]','depends = ["wrangler"]');
    o=o.replaceAll('depends = ["shep", "herd"]','depends = ["wrangler", "herd"]');
    o=o.replaceAll('daemons = ["shep"', 'daemons = ["wrangler"');
    // catch any remaining depends list containing shep in array form
    if(o.includes('"shep"')) o=o.replaceAll('"shep"','"wrangler"');
    return o===s?null:o;
  }],
  [`${ROOT}/src/services/registry.ts`, s=>{
    if(!s.includes("barn/shep")) return null;
    return s.replaceAll("barn/shep","barn/wrangler").replaceAll("shep-serve.sh","wrangler-serve.sh");
  }],
  [`${ROOT}/projects/range/bin/wrangler-serve.sh`, s=>{
    // also keep the source file updated for next boots
    if(s.includes("barn/wrangler")) return null;
    return s.replaceAll("barn/shep","barn/wrangler").replaceAll("# shep-serve.sh","# wrangler-serve.sh").replaceAll("launch shep","launch wrangler");
  }],
  [`${ROOT}/projects/range/bin/shep-serve.sh`, s=>{
    // patch legacy shep-serve.sh too (kept as symlink/compat)
    if(s.includes("barn/wrangler")) return null;
    return s.replaceAll("barn/shep","barn/wrangler").replaceAll("# shep-serve.sh","# wrangler-serve.sh").replaceAll("launch shep","launch wrangler");
  }],
];

const extra = execSync(`grep -r "barn/shep\\|\\\"shep\\\"\\|'shep'\\|/shep\\b" ${ROOT} --include="*.ts" --include="*.js" --include="*.sh" --include="*.toml" --include="*.md" --include="*.json" 2>/dev/null | tr -d '\\0' | strings | grep -v ELF | awk 'length<2000' | head -n 50`).toString();
console.log("--- grep shep refs (sample) ---\n"+extra);

for(const [f,fn] of targets) patch(f,fn);

// re-read patched pitchfork head
console.log("--- pitchfork head after ---");
console.log(execSync(`sed -n '1,45p' ${ROOT}/pitchfork.toml 2>&1 | tr -d '\\0' | strings | awk 'length<2000' | head -n 45`).toString());

// compat symlink for old callers during migration
try{ execSync(`ln -sf wrangler ${RANCH}/bin/shep 2>&1 | tr -d '\\0' | strings | awk 'length<2000' | head -n 5`); console.log("symlink barn/bin/shep -> wrangler"); }catch(e){ console.log("symlink skip "+String(e).slice(0,200)); }
try{ execSync(`ln -sf wrangler-serve.sh ${RANCH}/bin/shep-serve.sh 2>&1 | strings | awk 'length<2000' | head -n 5`); }catch{}
TS
bun run /tmp/rename-patch.ts 2>&1 | tr -d '\0' | strings | grep -v ELF | awk 'length<2000' | head -n 80

