import { readFileSync, writeFileSync, existsSync, mkdirSync, renameSync, cpSync, readdirSync, statSync, symlinkSync, lstatSync, unlinkSync } from "node:fs";
import { execSync } from "node:child_process";
const ROOT="/home/toxic/sovereign";
const pitch="/home/toxic/sovereign/pitchfork.toml";
const registry="/home/toxic/sovereign/src/services/registry.ts";
// 1. filesystem: wrangler binary (cp via shell, not Bun cpSync on ELF)
try{ execSync(`cp /home/toxic/sovereign/projects/range/bin/shep /home/toxic/sovereign/projects/range/bin/wrangler 2>&1 | tr -d '\\0' | strings | awk 'length<2000'`); console.log("cp shep->wrangler ELF"); }catch(e){ console.log("cp wrangler ELF fail "+String(e).slice(0,400)); }
try{ execSync(`cp /home/toxic/sovereign/projects/range/bin/shep-v0.51.0 /home/toxic/sovereign/projects/range/bin/wrangler-v0.51.0 2>&1 | tr -d '\\0' | strings | awk 'length<2000'`); console.log("cp v0.51.0"); }catch{}
// 2. patch pitchfork.toml: shep -> wrangler (daemon name, dir, run, depends, daemons lists)
let s=readFileSync(pitch,"utf8");
let o=s;
// daemons.shep -> daemons.wrangler (mark to avoid double)
o=o.replaceAll("[daemons.shep]","[__WRANGLER__]");
o=o.replaceAll("[__WRANGLER__]","[daemons.wrangler]");
// dir + run
o=o.replaceAll('dir = "/home/toxic/sovereign/projects/range/ranch/barn/shep"','dir = "/home/toxic/sovereign/projects/range/ranch/barn/wrangler"');
o=o.replaceAll("bin/shep-serve.sh","bin/wrangler-serve.sh");
o=o.replaceAll('"shep"','"wrangler"');
// fix comment line that had shep in prose
o=o.replaceAll("# shep-serve.sh","# wrangler-serve.sh");
if(o!==s){ writeFileSync(pitch,o); console.log("patched pitchfork.toml shep->wrangler"); } else console.log("pitchfork no diff");
// 3. registry.ts
let r=readFileSync(registry,"utf8");
let r2=r.replaceAll("barn/shep","barn/wrangler").replaceAll("shep-serve.sh","wrangler-serve.sh");
if(r2!==r){ writeFileSync(registry,r2); console.log("patched registry.ts"); }
// 4. bin/wrangler-serve.sh contents: ensure it references wrangler (idempotent)
for(const f of ["/home/toxic/sovereign/projects/range/bin/wrangler-serve.sh","/home/toxic/sovereign/projects/range/bin/shep-serve.sh"]){
  if(!existsSync(f)) continue;
  let t=readFileSync(f,"utf8");
  let u=t.replaceAll("barn/shep","barn/wrangler").replaceAll("# shep-serve.sh","# wrangler-serve.sh").replaceAll("launch shep","launch wrangler");
  if(u!==t){ writeFileSync(f,u); console.log("patched "+f); }
}
// 5. show heads
console.log("--- pitchfork 1..55 ---");
console.log(execSync(`sed -n '1,55p' ${pitch} 2>&1 | tr -d '\\0' | strings | awk 'length<2000' | head -n 55`).toString().slice(0,4000));
console.log("--- registry shep line ---");
console.log(execSync(`grep -n "wrangler\\|shep" ${registry} 2>&1 | tr -d '\\0' | strings | awk 'length<2000' | head -n 20`).toString());
