arguments.command:
bun -e '
import * as fs from "node:fs";
import * as path from "node:path";
import {execSync} from "node:child_process";
const sh=(cmd)=>{ try{return execSync(cmd,{encoding:"utf8",maxBuffer:16*1024*1024})} catch(e){ const x=e; return String(x.stdout||"")+String(x.stderr||"")+String(x.message).slice(0,1200)} };
const ok=(v)=>({ok:true,value:v});
const err=(e)=>({ok:false,error:e});
const flatMap=(r,f)=> r.ok ? f(r.value) : r;
const map=(r,f)=> r.ok ? ok(f(r.value)) : r;
const tap=(r,f)=>{ if(r.ok) try{f(r.value)}catch(e){}; return r; };

// helper: read file, apply patches, write if changed
type Patch = {file:string, find:RegExp, repl:string, label:string};
const patches:Patch[]=[
  {file:"/home/toxic/sovereign/pitchfork.toml", find:/\(shep direct-run/g, repl:"(wrangler direct-run", label:"pitchfork comment shep->wrangler"},
];
console.log("=== APPLYING PITCHFORK COMMENT PATCH (monadic) ===");
let result=ok(null);
for(const p of patches){
  result=flatMap(result, _=>{
    try{
      const txt=fs.readFileSync(p.file,"utf8");
      if(!p.find.test(txt)) return ok("skip "+p.label+" (no match)");
      const next=txt.replace(p.find, p.repl);
      // backup
      try{ fs.copyFileSync(p.file, p.file+".bak.wrangler-comment"); }catch{}
      fs.writeFileSync(p.file, next,"utf8");
      return ok("patched "+p.label);
    }catch(e){ return err(String(e).slice(0,800)); }
  });
  console.log(result.ok? "OK: "+JSON.stringify(result.value) : "ERR: "+result.error);
}

// now sweep bin scripts
console.log("\n=== SWEEP bin scripts (live) ===");
const binFiles=[
  "/home/toxic/sovereign/bin/tau-start.sh",
  "/home/toxic/sovereign/bin/chute-tau-fix.sh",
  "/home/toxic/sovereign/bin/audit-estate.sh",
];
for(const f of binFiles){
  let r=ok(fs.readFileSync(f,"utf8"));
  r=map(r, txt=> txt.replaceAll("[daemons.shep]","[daemons.wrangler]") );
  r=map(r, txt=> txt.replaceAll("depends = [\"shep\"]","depends = [\"wrangler\"]") );
  r=map(r, txt=> txt.replaceAll("depends = [\"shep\", \"herd\"]","depends = [\"wrangler\", \"herd\"]") );
  r=map(r, txt=> txt.replaceAll("depends = [\"shep\",","depends = [\"wrangler\",") );
  // also shep_idx var names
  r=map(r, txt=> txt.replaceAll("shep_idx","wrangler_idx") );
  r=map(r, txt=> txt.replaceAll("shepIdx","wranglerIdx") );
  // audit-estate shep health probe names -> wrangler (keep port)
  r=map(r, txt=> txt.replaceAll("check_port 25127 shep","check_port 25127 wrangler") );
  r=map(r, txt=> txt.replaceAll("probe_http \"shep\"","probe_http \"wrangler\"") );
  r=map(r, txt=> txt.replaceAll("summ \"shep\"","summ \"wrangler\"") );
  // file refs barn/shep
  r=map(r, txt=> txt.replaceAll("barn/shep","barn/wrangler") );
  r=map(r, txt=> txt.replaceAll("bin/shep-serve.sh","bin/wrangler-serve.sh") );
  r=map(r, txt=> txt.replaceAll("\"shep\"","\"wrangler\"") );
  if(r.ok){
    const orig=fs.readFileSync(f,"utf8");
    if(orig!==r.value){
      try{ fs.copyFileSync(f, f+".bak.wrangler"); }catch{}
      fs.writeFileSync(f, r.value,"utf8");
      console.log("PATCHED "+f+" ("+r.value.split("\n").filter(l=>l.includes("wrangler")).length+" wrangler lines)");
    } else console.log("SKIP "+f+" (no change)");
  } else console.log("ERR "+f+": "+r.error);
  // show live changed lines
  try{
    const after=fs.readFileSync(f,"utf8");
    console.log(after.split("\n").filter(l=> l.includes("wrangler") && l.length<2000).slice(0,6).join("\n") || "(no wrangler lines)");
  }catch{}
  console.log("---");
}

// tools fleet-ops shep files
console.log("\n=== tools fleet-ops shep-mcp live ===");
let fleetMcp="/home/toxic/sovereign/tools/fleet-ops/shep-mcp";
let fleetSh="/home/toxic/sovereign/tools/fleet-ops/shep-upstream-recover.sh";
for(const f of [fleetMcp, fleetSh]){
  if(!fs.existsSync(f)){ console.log("MISS "+f); continue; }
  const t=fs.readFileSync(f,"utf8");
  console.log(f+" first 400: "+t.slice(0,400).replace(/\n/g," | "));
  console.log(t.split("\n").filter(l=> l.includes("shep") && l.length<2000).slice(0,8).join("\n"));
}
' 2>&1 | tr -d '\0' | strings | rg -v ELF | awk 'length<2000'

