if(!st.isSymbolicLink()){
  let backup=process.env.HOME+"/.bashrc.bak."+Date.now();
  fs.copyFileSync(process.env.HOME+"/.bashrc", backup);
  console.log("BACKUP "+backup);
  fs.unlinkSync(process.env.HOME+"/.bashrc");
  fs.symlinkSync("/home/toxic/sovereign/projects/shell/ii/dots/.bashrc", process.env.HOME+"/.bashrc");
  console.log("RESTORED symlink ~/.bashrc -> dots/.bashrc");
