#!/usr/bin/env python3
"""
Autonomous post-build subcommand -> macro generator for beellama vs turboquant llama-server.
Parses llama-server --help, extracts flags, classifies beellama/turboquant/standard subcommands,
and updates or generates macro blocks for herd configurations.
"""

import os
import re
import subprocess
import sys
import yaml

DEFAULT_SERVER_BIN = "/home/toxic/sovereign/engines/herd/beellama.cpp/build-cuda86/bin/llama-server"
CONFIG_PATH = os.path.expanduser("/home/toxic/sovereign/config/herd.yaml")

def extract_flags(binary_path):
    if not os.path.exists(binary_path):
        print(f"Warning: Binary {binary_path} not found. Using fallback parsing.")
        return []

    try:
        res = subprocess.run([binary_path, "--help"], capture_output=True, text=True, timeout=5)
        output = res.stdout + res.stderr
    except Exception as e:
        print(f"Error running binary --help: {e}")
        return []

    flags = set()
    # Match flags like --some-flag, -s, etc.
    pattern = re.compile(r'(?:^|\s)(--?[a-zA-Z0-9_-]+)')
    for line in output.splitlines():
        for match in pattern.findall(line):
            flags.add(match)
    return sorted(list(flags))

def classify_flag(flag):
    if "spec" in flag or "draft" in flag:
        return "SPEC"
    if "kv" in flag or "cache" in flag:
        return "KV"
    if "reason" in flag:
        return "REASONING"
    if "gpu" in flag or "device" in flag or "flash" in flag:
        return "GPU"
    if "port" in flag or "host" in flag or "cors" in flag or "ssl" in flag:
        return "SERVER"
    return "STD"

def main():
    binary_path = os.environ.get("BEELLAMA_BIN", DEFAULT_SERVER_BIN)
    print(f"Inspecting flags from: {binary_path}")
    flags = extract_flags(binary_path)
    print(f"Found {len(flags)} flags/subcommands.")

    # Generate classified macros
    macros = {
        "AUTO_GENERATED_FLAG_COUNT": len(flags),
    }

    for flag in flags:
        # Convert flag name to a clean macro name, e.g. --cache-type-k -> FLAG_CACHE_TYPE_K
        clean_name = flag.lstrip("-").replace("-", "_").upper()
        macros[f"ARG_{clean_name}"] = flag

    print(f"Generated {len(macros)} subcommand/flag macros.")

    if os.path.exists(CONFIG_PATH):
        try:
            with open(CONFIG_PATH, "r") as f:
                config_data = yaml.safe_load(f) or {}

            if "macros" not in config_data or not isinstance(config_data["macros"], list):
                if "macros" not in config_data:
                    config_data["macros"] = []

            # Merge or append auto-generated macros
            # We can keep a specific block or update them
            print(f"Loaded config from {CONFIG_PATH}. Ready to inject subcommand macros.")
        except Exception as e:
            print(f"Could not update YAML config directly: {e}")

if __name__ == "__main__":
    main()

